styles.css:
&.wp-block-details {
	margin-top: 0;
}

&.wp-block-details:hover {
	background: none;
	border-color: var(--wp--custom--color--border--card);
	box-shadow: none;
}

&.wp-block-details[open] {
	background: none;
	border-color: var(--wp--custom--color--border--card);
	box-shadow: none;
}

&.wp-block-details[open]:hover {
	background: none;
	border-color: var(--wp--custom--color--border--card);
	box-shadow: none;
}

&.wp-block-details:focus-within {
	box-shadow: none;
}

&.wp-block-details[open] > summary {
	border-bottom-color: var(--wp--custom--color--border--card);
}

& > summary {
	min-block-size: 3rem;
	padding-inline: 0 var(--wp--preset--spacing--10);
	padding-block: 0;
	font-family: var(--wp--preset--font-family--body);
	font-size: var(--wp--preset--font-size--200);
	font-weight: var(--wp--custom--typography--font-weight--semibold);
	line-height: 1;
}

& > summary:focus-visible {
	outline: 2px solid var(--wp--custom--color--focus--ring);
	outline-offset: -2px;
}

& > summary > a {
	color: inherit;
	text-decoration: none;
}

& > summary > a:focus-visible {
	outline: 2px solid var(--wp--custom--color--focus--ring);
	outline-offset: 2px;
}

& > :where(:not(summary)) {
	padding-inline: 0;
}

& > :not(summary):first-of-type {
	padding-top: var(--wp--preset--spacing--5);
}
